// ===== MASTER COMMAND ROUTER =====
// Parses user messages and routes to appropriate actions

const msg = $input.first().json.message;
const text = (msg.text || '').toLowerCase().trim();
const chatId = msg.chat.id;
const userId = msg.from.id;

// Load state from workflow static data
const staticData = $getWorkflowStaticData('global');
if (!staticData.state) {
  staticData.state = {
    niche: null,
    brandIdentity: null,
    sampleCarousels: [],
    knowledgeBase: {},
    posts: [],
    phase: 'idle',
    igCredentials: null,
    competitors: [],
    audiencePersonas: [],
    hookFormulas: [],
    contentDNA: null,
    monetizationReady: false,
    lastResearchTime: null,
    postHistory: [],
    abTests: []
  };
}

const state = staticData.state;
let response = '';
let action = 'chat';
let actionData = {};

// ===== COMMAND PARSING =====

// Set Niche
if (text.startsWith('/niche ') || text.startsWith('set niche ') || text.startsWith('my niche is ')) {
  const niche = text.replace(/^(\/niche |set niche |my niche is )/, '').trim();
  state.niche = niche;
  state.phase = 'researching';
  action = 'start_research';
  actionData = { niche };
  response = `🔥 Niche locked: *${niche}*\n\n⚡ Starting deep research engine NOW. I'll scour TikTok, Instagram, Reddit, YouTube, Pinterest, LinkedIn, Twitter, Facebook groups, Google Trends, articles, and hundreds more sources.\n\nThis might take a bit — I'm going DEEP. I'll ping you when I've built the knowledge base. 🧠`;
}

// Set Brand Identity
else if (text.startsWith('/brand ') || text.startsWith('my brand ') || text.startsWith('set brand ')) {
  const brand = text.replace(/^(\/brand |my brand |set brand )/, '').trim();
  state.brandIdentity = brand;
  response = `🎨 Brand identity locked: *${brand}*\n\nNow upload your sample carousel images so I can match the style! 📸`;
}

// Upload Sample Carousel (when user sends images)
else if (msg.photo && state.phase !== 'idle') {
  const photoId = msg.photo[msg.photo.length - 1].file_id;
  state.sampleCarousels.push(photoId);
  response = `📸 Got carousel sample #${state.sampleCarousels.length}! ${state.sampleCarousels.length >= 3 ? 'Enough samples — I can now match your style! ✅' : 'Send more if you have them!'}`;
}

// Set IG Credentials
else if (text.startsWith('/ig ') || text.startsWith('set ig ') || text.startsWith('instagram ')) {
  const creds = text.replace(/^(\/ig |set ig |instagram )/, '').trim();
  const parts = creds.split(' ');
  if (parts.length >= 2) {
    state.igCredentials = { username: parts[0], password: parts.slice(1).join(' ') };
    response = `✅ IG credentials saved for @${parts[0]}\n\n⚠️ These are stored securely in n8n credentials. Let's go! 🔥`;
  } else {
    response = `❌ Format: /ig username password`;
  }
}

// Start Content Creation
else if (text.startsWith('/create') || text === 'create' || text === 'make post' || text.startsWith('make a post') || text.startsWith('create post') || text.startsWith('post something')) {
  if (!state.niche) {
    response = `❌ Set your niche first! Example: /niche fitness`;
  } else if (!state.brandIdentity) {
    response = `❌ Set your brand first! Example: /brand minimalist fitness brand with dark theme`;
  } else {
    action = 'create_content';
    response = `🚀 Creating carousel based on my research...\n\nGive me a moment — I'm picking the best hook, angle, and design based on what's working RIGHT NOW in ${state.niche} 🔥`;
  }
}

// Research Status
else if (text === '/status' || text === 'status' || text === 'how are things' || text === 'progress') {
  const postCount = state.posts.length;
  const lastPost = state.posts.length > 0 ? state.posts[state.posts.length - 1] : null;
  const kbSize = Object.keys(state.knowledgeBase).length;

  response = `📊 *STATUS REPORT*\n\n`;
  response += `🎯 Niche: ${state.niche || 'Not set'}\n`;
  response += `🎨 Brand: ${state.brandIdentity || 'Not set'}\n`;
  response += `📸 Carousel Samples: ${state.sampleCarousels.length}\n`;
  response += `🧠 Knowledge Base: ${kbSize} data points\n`;
  response += `📝 Posts Made: ${postCount}\n`;
  response += `🔬 Phase: ${state.phase}\n`;
  response += `💰 Monetization: ${state.monetizationReady ? 'READY 🔥' : 'Not yet'}\n`;

  if (lastPost) {
    response += `\n📈 *Last Post Performance:*\n`;
    response += `👁️ Views: ${lastPost.views || 'Tracking...'}\n`;
    response += `❤️ Likes: ${lastPost.likes || 'Tracking...'}\n`;
    response += `💬 Comments: ${lastPost.comments || 'Tracking...'}\n`;
    response += `📤 Saves: ${lastPost.saves || 'Tracking...'}\n`;
  }
}

// Research Now
else if (text === '/research' || text === 'research' || text === 'research now' || text === 'update knowledge') {
  action = 'start_research';
  actionData = { niche: state.niche };
  response = `🔄 Starting fresh research sweep across ALL platforms...\n\nI'll update the knowledge base with the latest data. 🧠⚡`;
}

// Show Knowledge
else if (text === '/knowledge' || text === 'knowledge' || text === 'what do you know' || text === 'show knowledge') {
  const kb = state.knowledgeBase;
  response = `🧠 *KNOWLEDGE BASE SUMMARY*\n\n`;
  response += `📊 Top Hooks: ${(kb.topHooks || []).slice(0, 5).join(', ') || 'Still learning...'}\n`;
  response += `🏷️ Top Hashtags: ${(kb.topHashtags || []).slice(0, 10).join(', ') || 'Still learning...'}\n`;
  response += `⏰ Best Post Times: ${(kb.bestTimes || []).slice(0, 3).join(', ') || 'Still learning...'}\n`;
  response += `🎯 Top CTAs: ${(kb.topCTAs || []).slice(0, 5).join(', ') || 'Still learning...'}\n`;
  response += `👥 Audience Pain Points: ${(kb.painPoints || []).slice(0, 5).join(', ') || 'Still learning...'}\n`;
  response += `🔥 Trending Topics: ${(kb.trendingTopics || []).slice(0, 5).join(', ') || 'Still learning...'}\n`;
  response += `🏆 Competitors Tracked: ${(kb.competitors || []).length}\n`;
  response += `💡 Content Ideas: ${(kb.contentIdeas || []).length}\n`;
  response += `\n📚 Total data points: ${Object.keys(kb).length}`;
}

// Analytics
else if (text === '/analytics' || text === 'analytics' || text === 'how are posts doing' || text === 'show analytics') {
  action = 'get_analytics';
  response = `📊 Pulling latest analytics...`;
}

// Viral Alert Check
else if (text === '/viral' || text === 'viral' || text === 'anything going viral' || text === 'trending') {
  action = 'check_trends';
  response = `🔍 Checking what's going VIRAL in ${state.niche} right now...`;
}

// Monetization Discussion
else if (text === '/monetize' || text === 'monetize' || text === 'time to monetize' || text === 'lets monetize') {
  action = 'monetize';
  response = `💰 Let's talk money! Analyzing your audience and niche for the best monetization strategy...`;
}

// Help
else if (text === '/help' || text === 'help' || text === 'what can you do') {
  response = `🤖 *NEO IG MACHINE - COMMANDS*\n\n`;
  response += `🎯 *Setup:*\n`;
  response += `/niche [name] — Set your niche\n`;
  response += `/brand [description] — Set brand identity\n`;
  response += `/ig [user] [pass] — Set IG credentials\n`;
  response += `📸 Upload carousel samples as images\n\n`;
  response += `🚀 *Actions:*\n`;
  response += `create / make post — Generate & post carousel\n`;
  response += `research — Update knowledge base\n`;
  response += `status — Check progress\n`;
  response += `knowledge — See what I've learned\n`;
  response += `analytics — Post performance\n`;
  response += `viral / trending — Check viral content\n`;
  response += `monetize — Monetization strategy\n\n`;
  response += `💬 *Chat:*\n`;
  response += `Talk to me normally! Ask me anything about ${state.niche || 'your niche'} 🧠`;
}

// Free Chat (AI Response)
else {
  action = 'ai_chat';
  actionData = { message: text, state: state };
  response = null; // Will be generated by AI
}

return [{
  json: {
    chatId,
    userId,
    text,
    response,
    action,
    actionData,
    state
  }
}];
